#include <cplib/collections/bitset.hpp>
#include <random>
using namespace cplib;
template<Int N> void test(){std::mt19937 rng(N);for(int trial=0;trial<100;++trial){std::vector<bool> a(N),b(N);std::vector<Int> indices;for(Int i=0;i<N;++i){a[i]=rng()%2;b[i]=rng()%2;if(a[i])indices.push_back(i);}auto d=initBitSet(a);auto e=initBitSet(b);auto s=ScalarBitSet<N>(a);auto t=ScalarBitSet<N>(b);assert(d==initBitSetFromIndexes(indices,N));auto check=[&](const auto& set,const std::vector<bool>& v){Int count=0;std::vector<Int> positions;std::string str;for(Int i=0;i<N;++i){assert(bool(set[i])==v[i]);count+=v[i];if(v[i])positions.push_back(i);str+=v[i]?'1':'0';}assert(set.popcount()==count&&set.all()==(count==N)&&set.any()==bool(count));assert(set.lowestBit()==(positions.empty()?-1:positions[0]));std::vector<Int> actual;for(Int i:set)actual.push_back(i);assert(actual==positions);std::reverse(str.begin(),str.end());assert(set.to_string()==str);};check(d,a);check(s,a);assert((s<t)==std::lexicographical_compare(a.begin(),a.end(),b.begin(),b.end())&&(d<e)==(s<t));for(Int shift:std::array<Int,8>{0,1,7,63,64,65,N,N+1}){std::vector<bool> left(N),right(N);for(Int i=0;i<N;++i){if(i+shift<N)left[i+shift]=a[i];if(i>=shift)right[i-shift]=a[i];}check(d<<shift,left);check(s<<shift,left);check(d>>shift,right);check(s>>shift,right);}std::vector<bool> both(N),either(N),diff(N),neg(N);for(Int i=0;i<N;++i){both[i]=a[i]&&b[i];either[i]=a[i]||b[i];diff[i]=a[i]!=b[i];neg[i]=!a[i];}check(d&e,both);check(s&t,both);check(d|e,either);check(s|t,either);check(d^e,diff);check(s^t,diff);check(~d,neg);check(~s,neg);auto copy=s;copy&=t;check(copy,both);copy=s;copy|=t;check(copy,either);copy=s;copy^=t;check(copy,diff);assert(andpopcount(d,e)==(d&e).popcount()&&orpopcount(s,t)==(s|t).popcount()&&xorpopcount(s,t)==(s^t).popcount());if(N){d[from_end(1)]=!a.back();s[from_end(1)]=!a.back();a.back()=!a.back();d[0]=2;s[0]=2;check(d,a);check(s,a);}}}
int main(){test<0>();test<1>();test<63>();test<64>();test<65>();test<127>();test<128>();test<257>();test<1024>();bool threw=false;try{initBitSet(-1);}catch(const std::invalid_argument&){threw=true;}assert(threw);threw=false;try{auto a=initBitSet(10),b=initBitSet(11);(void)(a&b);}catch(const std::invalid_argument&){threw=true;}assert(threw);threw=false;try{(void)initBitSetFromIndexes({10},10);}catch(const std::out_of_range&){threw=true;}assert(threw);}
